#include "../core/material_emission.h"
#include <iostream>
using namespace P4MapKit::Material;
static int checks=0;
static void Check(bool good,const char* name){++checks;if(!good)throw std::runtime_error(name);}
template<class F>static void Refuses(F action,const char* category){bool hit=false;try{action();}catch(const Refused& e){hit=e.name==category;}Check(hit,"named material schedule refusal");}
int main(){try{
    const std::vector<std::string> lines={"LDC.F32 R0.x, buf1[0]","LDC.F32 R7.x, buf1[4]","ADD.F R1.x, R0.x, {2}.x","MUL.F R5.x, R7.x, {10}.x","MUL.F R2.x, R1.x, {3}.x","MOV.F result_color0.w, R2.x"};
    const auto code=ParseMaterialAnchorInstructions(lines);auto delayed=BuildDelayedMaterialAnchor(code,2,5,code[5].src[0]);Check(delayed.Indices==std::vector<std::size_t>{2,4}&&delayed.ScheduledLine==5,"slice omits independent lighting");
    SymbolicMachine prefix(lines);prefix.run(2);auto values=ReadScheduledMaterialValue(lines,delayed,prefix);SymbolicMachine whole(lines,prefix.arena);whole.run(5);Check(values.size()==1&&same(values[0],whole.reg.at("R2")[0]),"sliced value equals original unsliced symbolic value");Check(!prefix.reg.count("R1")&&!prefix.reg.count("R2"),"reading a schedule preserves the prefix");
    auto constant=BuildDelayedMaterialAnchor(code,2,5,AnchorOperand("{1,2,3,4}.z"));Check(constant.ValueAnchor.has_constant&&ReadScheduledMaterialValue(lines,constant,prefix)[0].number()==3,"literal schedule uses exact component");
    Refuses([&]{BuildDelayedMaterialAnchor(code,2,5,AnchorOperand("-R2.x"));},"material scheduled transformed output");Refuses([&]{BuildDelayedMaterialAnchor(code,6,5,code[5].src[0]);},"material scheduled range");
    const auto conditional=ParseMaterialAnchorInstructions({"MOV.F R0.x, {1}.x","IF R7.x","MUL.F R2.x, R0.x, {3}.x","ENDIF","MOV.F result_color0.w, R2.x"});Refuses([&]{BuildDelayedMaterialAnchor(conditional,1,4,conditional[4].src[0]);},"material scheduled conditional write");
    const auto predicate=ParseMaterialAnchorInstructions({"MOV.F R0.x, {1}.x","MUL.F R2.x (NE.x), R0.x, {3}.x","MOV.F result_color0.w, R2.x"});Refuses([&]{BuildDelayedMaterialAnchor(predicate,1,2,predicate[2].src[0]);},"material scheduled conditional write");
    const auto arrayCode=ParseMaterialAnchorInstructions({"MOV.F A[0].x, {1}.x","MOV.F A[1].x, {2}.x","MOV.F I.x, {0}.x","MUL.F R2.x, A[I.x].x, {3}.x","MOV.F result_color0.w, R2.x"});auto arraySchedule=BuildDelayedMaterialAnchor(arrayCode,0,4,arrayCode[4].src[0]);Check(arraySchedule.Indices==std::vector<std::size_t>{0,1,2,3},"finite array conservatively keeps every initialized entry");
    auto missingArray=arrayCode;missingArray[1]=AnchorInstruction("MOV.F A[1].y, {2}.x");Refuses([&]{BuildDelayedMaterialAnchor(missingArray,0,4,missingArray[4].src[0]);},"material scheduled array initialization");
    auto wrongLines=lines;wrongLines[4]="MUL.F R2.x, R1.x, {4}.x";Refuses([&]{ReadScheduledMaterialValue(wrongLines,delayed,prefix);},"material scheduled program");
    auto badOrder=delayed;badOrder.Indices={4,2};Refuses([&]{ReadScheduledMaterialValue(lines,badOrder,prefix);},"material scheduled range");
    auto dot=MaterialInstructionReads(AnchorInstruction("DP3.F R1.x, R0.wxyz, R7.zxyw"),"x");Check(dot.count({"R0",'w'})&&dot.count({"R0",'x'})&&dot.count({"R0",'y'})&&!dot.count({"R0",'z'})&&dot.count({"R7",'z'}),"dot reads three swizzled components");
    const auto emission=ParseMaterialAnchorInstructions({"MOV.F R0.xyz, {1,2,3}","MUL.F R2.xyz, R0.xyz, {2}.x","MAX.F R5.xyz, R2.xyz, {0}.x","ADD.F R6.xyz, R7.xyz, R5.xyz","MUL.F result_color0.xyz, R6.xyz, {1}.x"});auto emissionAnchor=FindScheduledMaterialEmissiveAnchor(emission,1);Check(emissionAnchor.Found&&emissionAnchor.ClampLine==2&&emissionAnchor.AddLine==3&&emissionAnchor.Value.Indices==std::vector<std::size_t>{1}&&emissionAnchor.Value.ValueAnchor.comps=="xyz","late native emissive slice precedes exact engine clamp and add");auto noConsumer=emission;noConsumer[3]=AnchorInstruction("ADD.F R6.xyz, R7.xyz, R8.xyz");Check(!FindScheduledMaterialEmissiveAnchor(noConsumer,1).Found,"unconsumed clamp is no emission boundary");auto twoConsumers=emission;twoConsumers.insert(twoConsumers.begin()+4,AnchorInstruction("MAX.F R9.xyz, R0.xyz, {0}.x"));twoConsumers.insert(twoConsumers.begin()+5,AnchorInstruction("ADD.F R10.xyz, R7.xyz, R9.xyz"));Refuses([&]{FindScheduledMaterialEmissiveAnchor(twoConsumers,1);},"material emissive consumers");Refuses([&]{BuildDelayedMaterialVectorAnchor(emission,1,2,AnchorOperand("{1,2,3}"));},"material scheduled vector");
    std::cout<<"native material schedule checks="<<checks<<"\n";
}catch(const std::exception& error){std::cerr<<error.what()<<"\n";return 1;}return 0;}
